function a(o,t){let e=o;if(e?.status===0)return"Sem conex\xE3o com o servidor. Confira sua conex\xE3o e tente novamente.";if(e?.status===401)return"Sua sess\xE3o expirou. Entre novamente para continuar.";if(e?.status===403)return"Voc\xEA n\xE3o tem permiss\xE3o para realizar esta opera\xE7\xE3o.";if(e?.status&&e.status>=500)return"O servidor n\xE3o conseguiu concluir a opera\xE7\xE3o. Tente novamente.";let r=Object.entries(e?.error?.campos??{}).map(([n,s])=>`${n}: ${s}`);return r.length?r.join("; "):e?.error?.mensagem||t}export{a};
